insert into support_resources (id, title, category, summary, body, source_label, published)
values
  ('resource-questions', 'Questions to bring to your care team', 'appointments', 'Use these prompts to guide a conversation with your clinician.', 'You may want to ask: What is the goal of this treatment? What benefits should I expect, and how will we know whether it is working? What side effects should I watch for, and which ones need an urgent call? Who should I contact after hours? Are there supportive-care services or clinical trials that may be relevant to me? Ask your clinician to explain terms that are unfamiliar and to help prioritize your questions.', 'CancerCompanion educational content', true),
  ('resource-clinical-trials', 'Learning about clinical trials', 'treatment', 'A clinical trial is a research study that evaluates a health intervention.', 'Clinical trials have eligibility criteria, study procedures, possible benefits, and risks. Ask your oncology team whether any trials may be relevant to your diagnosis and circumstances. Before deciding, discuss the purpose of the study, the treatment being studied, alternatives, potential costs, travel, and the right to leave the study. A trial is not automatically better than standard care.', 'CancerCompanion educational content', true),
  ('resource-food-hydration', 'Food and hydration during treatment', 'wellbeing', 'Treatment may affect appetite, taste, digestion, and fluid needs.', 'Ask your care team whether you should meet with an oncology dietitian. Tell them about nausea, swallowing difficulty, diarrhoea, constipation, mouth soreness, weight changes, food restrictions, or trouble keeping fluids down. Your nutrition needs can change with treatment, so seek individualized guidance rather than following a restrictive diet or supplement plan without clinical advice.', 'CancerCompanion educational content', true)
